function walk(node,name){ if(node.type==="COMPONENT"&&node.name===name)return node; for(const c of node.children||[]){const r=walk(c,name);if(r)return r;} return null; }
function findComp(name){ for(const p of figma.root.children){const r=walk(p,name);if(r)return r;} return null; }
function inst(name){ const c=findComp(name); if(!c) throw new Error("no comp "+name); return c.createInstance(); }
