function rect(p,x,y,w,h,fill,r){ const n=figma.createRectangle(); p.appendChild(n); n.x=x;n.y=y;n.resize(w,h); if(fill!=null){n.fills=[{type:"SOLID",color:hex(fill)}];} else n.fills=[]; if(r!=null)n.cornerRadius=r; return n; }
