function dump(node, depth){
  let line="";
  for(let i=0;i<depth;i++)line+="  ";
  console.log(line+node.type+" | "+node.name+" | "+(node.characters||"")+" | font="+(node.fontName?node.fontName.family+"/"+node.fontName.style:""));
