async function setLabel(frame, label){
  const btn = frame.findOne(n=>n.type==="INSTANCE" && n.name==="Button");
  if(!btn){ console.log(frame.name+": no Button"); return; }
  const txt = btn.findOne(n=>n.type==="TEXT");
  if(txt){ await figma.loadFontAsync(txt.fontName); txt.characters=label; console.log(frame.name+": set '"+label+"'"); }
