const page=figma.root.children.find(p=>p.name==="03 · Workspace");
const active = {"08_Home":"Home","14_Chats":"Chat","15_Chat":"Chat","16_Prescriptions":"Visits"};
await figma.loadFontAsync({family:"Plus Jakarta Sans",style:"SemiBold"});
const GREEN={r:0x66/255,g:0xCA/255,b:0x98/255};
const GRAY={r:0x9a/255,g:0x9f/255,b:0xa6/255};
for(const fr of page.children){
  const activeTab = active[fr.name];
  if(!activeTab) continue;
  const tab = fr.findOne(n=>n.type==="INSTANCE" && n.name==="TabBar");
  if(!tab){ console.log(fr.name+": no tabbar"); continue; }
  const tabs = tab.findAll(n=>n.type==="FRAME" && n.name.indexOf("Tab_")===0);
  for(const t of tabs){
    const label = t.name.replace("Tab_","");
    const isActive = (label===activeTab);
    const txt = t.findOne(n=>n.type==="TEXT");
    if(txt){ await figma.loadFontAsync(txt.fontName); }
    // set label color
