function has(cname){ return !!compByName[cname]; }
function nameOf(id){ const n=figma.getNodeById(id); return n?n.name:"?"; }

// Helper: replace existing instance with a new instance of target component, keeping pos/size
async function replaceWith(node, compName){
  if(!compByName[compName]){ return "MISSING-SRC:"+compName; }
  const x=node.x, y=node.y, w=node.width, h=node.height, idx=node.parent.children.indexOf(node);
  const nc=compByName[compName].createInstance();
  nc.x=x; nc.y=y; nc.resize(w,h);
  node.remove();
  node.parent.insertChild(idx, nc);
  return "OK->"+compName;
}

